<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Registration numbers</title>@vite(['resources/css/app.css','resources/js/app.js'])</head><body>@include('core._shell-start')<main class="ad-page st-page"><header class="ad-page-head"><div><p class="ad-eyebrow">Administration</p><h1>Registration numbers</h1><p>Choose the format used when a pupil receives a number.</p></div></header>@if(session('status'))<div class="oak-notice oak-notice-success">{{ session('status') }}</div>@endif @if($errors->any())<div class="oak-notice oak-notice-danger">{{ $errors->first() }}</div>@endif
<form method="post" action="{{ route('registration-numbers.update') }}" class="st-settings">@csrf @method('put')<section class="ad-card"><div class="ad-card-head"><div><h2>School format</h2><p>Changing the format affects new numbers only.</p></div></div><div class="ad-form-grid"><label>School prefix<input name="registration_prefix" value="{{ old('registration_prefix',$settings->registration_prefix) }}" required minlength="2" maxlength="6"><small>2–6 letters or numbers. Saved in upper case.</small></label><label>Minimum number length<select name="registration_number_length">@foreach(range(3,6) as $length)<option value="{{ $length }}" @selected((int)$settings->registration_number_length===$length)>{{ $length }} digits</option>@endforeach</select><small>Larger numbers grow beyond this width; they are never cut off.</small></label><label class="ad-tick"><span><b>Include the year</b><small>The calendar year when the number is created.</small></span><input type="checkbox" name="registration_include_year" value="1" @checked($settings->registration_include_year)></label></div><div class="st-example"><b>Examples</b><code data-number-example></code></div></section>
<section class="ad-card"><div class="ad-card-head"><div><h2>Prefix by Section and Level</h2><p>A Level prefix wins, then its Section prefix, then the school prefix.</p></div></div>@foreach($sections as $section)<div class="st-prefix-group"><label>{{ $section->name }} prefix<input name="section_prefixes[{{ $section->id }}]" value="{{ old('section_prefixes.'.$section->id,$section->registration_prefix) }}" placeholder="Uses school prefix"></label>@foreach($section->levels as $level)<label>{{ $level->name }} prefix<input name="level_prefixes[{{ $level->id }}]" value="{{ old('level_prefixes.'.$level->id,$level->registration_prefix) }}" placeholder="Uses {{ $section->registration_prefix ?: $settings->registration_prefix }}"></label>@endforeach</div>@endforeach</section>
<section class="ad-card"><div class="ad-card-head"><div><h2>When a pupil moves to a different prefix</h2><p>{{ $locked ? 'This choice is locked because a pupil already has a number.' : 'This choice locks when the first number is issued.' }}</p></div></div>@foreach([\App\Modules\Admissions\Services\RegistrationNumbers::KEEP_DIGITS_CHANGE_PREFIX=>['Keep the digits, change the prefix','Oakfield default.'],\App\Modules\Admissions\Services\RegistrationNumbers::NEW_PREFIX_SEQUENCE=>['Give a new number from that prefix','Each prefix has its own counter.'],\App\Modules\Admissions\Services\RegistrationNumbers::KEEP_WHOLE_NUMBER=>['Keep the whole number as issued','The prefix and digits do not change.']] as $value=>$copy)<label class="ad-tick"><span><b>{{ $copy[0] }}</b><small>{{ $copy[1] }}</small></span><input type="radio" name="registration_move_policy" value="{{ $value }}" @checked($settings->registration_move_policy===$value) @disabled($locked && $settings->registration_move_policy!==$value)></label>@endforeach</section>
<section class="ad-card"><div class="ad-card-head"><div><h2>Next number</h2><p>It cannot be set below the highest number already issued.</p></div></div><label>School-wide sequence<input type="number" min="1" name="next_numbers[school]" value="{{ $sequences->get('school')?->next_number ?? 1 }}"></label>@foreach($sequences->filter(fn($row)=>str_starts_with($row->sequence_key,'prefix:')) as $row)<label>{{ substr($row->sequence_key,7) }} sequence<input type="number" min="1" name="next_numbers[{{ $row->sequence_key }}]" value="{{ $row->next_number }}"></label>@endforeach</section>
<section class="ad-card"><div class="ad-card-head"><div><h2>Where numbers are used</h2><p>Current application check.</p></div></div><div class="ad-scroll"><table class="ad-table"><thead><tr><th>Place</th><th>Current use</th></tr></thead><tbody><tr><td>Students</td><td>Shown and searchable, including earlier numbers</td></tr><tr><td>Student sign-in and number</td><td>Shown with history</td></tr><tr><td>Incoming from Primary</td><td>Shown when present</td></tr><tr><td>Not invoiced</td><td>Shown when present</td></tr><tr><td>Record payment search</td><td>The field mentions registration number, but the server currently searches name or username only</td></tr><tr><td>Receipts and invoice detail</td><td>Not shown today</td></tr><tr><td>Report cards</td><td>Not shown today</td></tr><tr><td>Sign-in slips and login</td><td>The sign-in rules say the registration number is not the username</td></tr></tbody></table></div></section><div class="ad-bar"><button class="oak-btn oak-btn-primary">Save settings</button></div></form></main>@include('core._shell-end') @livewireScripts<script>const prefix=document.querySelector('[name=registration_prefix]'),length=document.querySelector('[name=registration_number_length]'),year=document.querySelector('[name=registration_include_year]'),example=document.querySelector('[data-number-example]');const updateExample=()=>{const parts=[prefix.value.trim().toUpperCase()||'REG'];if(year.checked)parts.push('{{ now('Africa/Lagos')->format('Y') }}');parts.push('1'.padStart(Number(length.value),'0'));example.textContent=parts.join('-')};[prefix,length,year].forEach(field=>field.addEventListener('input',updateExample));updateExample()</script></body></html>
